use superposition_mcp::McpServer;

#[tokio::test]
async fn lists_all_85_tools() {
    let client = superposition_sdk::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();
    let names = router.tool_names();
    assert_eq!(names.len(), 85, "Expected 85 tools, got {}", names.len());
}

#[tokio::test]
async fn tool_names_include_expected_operations() {
    let client = superposition_sdk::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();
    let names = router.tool_names();
    let expected = vec![
        "CreateExperiment",
        "GetConfig",
        "ListAuditLogs",
        "CreateWorkspace",
        "DeleteContext",
        "UpdateWebhook",
        "WeightRecompute",
    ];
    for name in expected {
        assert!(names.contains(&name.to_string()), "Missing tool: {}", name);
    }
}

#[tokio::test]
async fn call_unknown_tool_returns_error() {
    let client = superposition_sdk::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();
    let result = router.test_call_tool("NonExistent", serde_json::json!({})).await;
    assert!(result.is_err());
}

/// Calling a tool with empty params returns an error when the input type has required fields.
/// This verifies the tool handler is wired up and deserialization validation works.
#[tokio::test]
async fn call_create_experiment_with_empty_params_returns_error() {
    let client = superposition_sdk::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();
    let result = router.test_call_tool("CreateExperiment", serde_json::json!({})).await;
    assert!(result.is_err(), "Expected deserialization error for empty params");
}

/// RotateMasterEncryptionKey takes a Unit input (no required fields),
/// so calling with empty params should succeed.
#[tokio::test]
async fn call_rotate_master_encryption_key_succeeds_with_empty_params() {
    let client = superposition_sdk::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();
    let result = router.test_call_tool("RotateMasterEncryptionKey", serde_json::json!({})).await;
    assert!(result.is_ok(), "Expected success for Unit input: {:?}", result.err());
}

use weather_mcp::McpServer;

#[tokio::test]
async fn lists_all_registered_tools() {
    let client = weather_client::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();

    let mut names = router.tool_names();
    names.sort();
    assert_eq!(names, vec!["GetForecast", "GetWeather"]);
}

#[tokio::test]
async fn call_get_weather_returns_data() {
    let client = weather_client::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();

    let params = serde_json::json!({ "city": "Seattle" });
    let result = router.test_call_tool("GetWeather", params).await.unwrap();

    assert_eq!(result["temperature"], 72.0);
    assert!(result["conditions"].as_str().unwrap().contains("Seattle"));
    assert_eq!(result["humidity"], 45.0);
}

#[tokio::test]
async fn call_get_forecast_returns_correct_days() {
    let client = weather_client::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();

    let params = serde_json::json!({ "city": "Portland", "days": 3 });
    let result = router.test_call_tool("GetForecast", params).await.unwrap();

    let forecasts = result["forecasts"].as_array().unwrap();
    assert_eq!(forecasts.len(), 3);
    assert_eq!(forecasts[0]["date"], "2024-01-01");
    assert_eq!(forecasts[0]["conditions"], "Partly Cloudy");
}

#[tokio::test]
async fn call_unknown_tool_returns_error() {
    let client = weather_client::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();

    let params = serde_json::json!({});
    let result = router.test_call_tool("NonExistent", params).await;

    assert!(result.is_err());
}

#[tokio::test]
async fn call_with_invalid_params_returns_error() {
    let client = weather_client::Client::new();
    let server = McpServer::new(client);
    let router = server.into_router();

    // Missing required "city" field — deserialization should fail
    let params = serde_json::json!({ "wrong_field": 123 });
    let result = router.test_call_tool("GetWeather", params).await;

    assert!(result.is_err());
}

package software.amazon.smithy.mcp.codegen;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class RustWriterTest {

    @Test
    void writesLineWithIndent() {
        RustWriter w = new RustWriter();
        w.writeLine("use serde::Serialize;");
        w.writeLine("");
        w.openBlock("pub struct Foo {");
        w.writeLine("pub name: String,");
        w.closeBlock("}");

        String expected = "use serde::Serialize;\n"
                + "\n"
                + "pub struct Foo {\n"
                + "    pub name: String,\n"
                + "}\n";
        assertEquals(expected, w.toString());
    }

    @Test
    void handlesNestedBlocks() {
        RustWriter w = new RustWriter();
        w.openBlock("impl Foo {");
        w.openBlock("pub fn bar() {");
        w.writeLine("println!(\"hello\");");
        w.closeBlock("}");
        w.closeBlock("}");

        String expected = "impl Foo {\n"
                + "    pub fn bar() {\n"
                + "        println!(\"hello\");\n"
                + "    }\n"
                + "}\n";
        assertEquals(expected, w.toString());
    }
}

