package software.amazon.smithy.mcp.codegen;

import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import software.amazon.smithy.build.FileManifest;
import software.amazon.smithy.build.PluginContext;
import software.amazon.smithy.model.Model;
import software.amazon.smithy.model.node.Node;
import software.amazon.smithy.model.node.ObjectNode;

import static org.junit.jupiter.api.Assertions.*;

class IntegrationTest {

    @TempDir
    Path outputDir;

    private PluginContext createContext(String modelResource, ObjectNode settings) {
        Model model = Model.assembler()
                .discoverModels(getClass().getClassLoader())
                .addImport(getClass().getResource(modelResource))
                .assemble()
                .unwrap();

        FileManifest manifest = FileManifest.create(outputDir);
        return PluginContext.builder()
                .model(model)
                .fileManifest(manifest)
                .settings(settings)
                .build();
    }

    @Test
    void generatesMultiToolService() throws Exception {
        ObjectNode settings = Node.objectNodeBuilder()
                .withMember("service", "com.example#MultiService")
                .withMember("package", "multi_mcp")
                .withMember("clientSdk", "smithy-rs")
                .withMember("clientCrate", "multi-client")
                .build();

        PluginContext context = createContext("integration-test.smithy", settings);
        new McpGeneratePlugin().execute(context);

        String types = Files.readString(outputDir.resolve("src/types.rs"));
        assertTrue(types.contains("pub struct CreateItemInput"));
        assertTrue(types.contains("pub struct ListItemsInput"));
        // Verify transitive structure collection: Item is referenced via ItemList in ListItemsOutput
        assertTrue(types.contains("pub struct Item"));

        // Verify enum generation
        assertTrue(types.contains("pub enum ItemStatus {"), "Expected enum ItemStatus in types.rs:\n" + types);
        assertTrue(types.contains("#[serde(rename = \"ACTIVE\")]"), "Expected ACTIVE serde rename:\n" + types);
        assertTrue(types.contains("#[serde(rename = \"INACTIVE\")]"), "Expected INACTIVE serde rename:\n" + types);

        // Verify struct references the enum type
        assertTrue(types.contains("pub status: ItemStatus,"), "Expected struct to reference enum type:\n" + types);

        String tools = Files.readString(outputDir.resolve("src/tools.rs"));
        assertTrue(tools.contains("handle_create_item"));
        assertTrue(tools.contains("handle_list_items"));

        String server = Files.readString(outputDir.resolve("src/server.rs"));
        assertTrue(server.contains("tool_info_create_item"));
        assertTrue(server.contains("tool_info_list_items"));
        // Verify router-based tool registration with closures
        assertTrue(server.contains("router.register_tool(tools::tool_info_create_item()"));
        assertTrue(server.contains("router.register_tool(tools::tool_info_list_items()"));
        assertTrue(server.contains("tools::handle_create_item"));
        assertTrue(server.contains("tools::handle_list_items"));
        assertTrue(server.contains("pub async fn serve_stdio(self)"));
        assertFalse(server.contains("call_tool"));
    }

    @Test
    void generatesCustomSdkMode() throws Exception {
        ObjectNode settings = Node.objectNodeBuilder()
                .withMember("service", "com.example#MultiService")
                .withMember("package", "multi_mcp")
                .withMember("clientSdk", "custom")
                .withMember("clientCrate", "multi-client")
                .build();

        PluginContext context = createContext("integration-test.smithy", settings);
        new McpGeneratePlugin().execute(context);

        String server = Files.readString(outputDir.resolve("src/server.rs"));
        assertTrue(server.contains("pub trait ToolHandler"));
        assertTrue(server.contains("pub fn new(handler: Arc<dyn ToolHandler>)"));
        assertTrue(server.contains("use async_trait::async_trait;"));
        assertTrue(server.contains("use std::sync::Arc;"));
        assertTrue(server.contains("use crate::types::*;"));
        // Verify custom mode dispatch passes handler via closure
        assertTrue(server.contains("&*handler"));

        String tools = Files.readString(outputDir.resolve("src/tools.rs"));
        assertTrue(tools.contains("use crate::server::ToolHandler;"));
        assertFalse(tools.contains("use serde_json;"));
    }

    @Test
    void skipsOperationsWithoutMcpToolTrait() throws Exception {
        ObjectNode settings = Node.objectNodeBuilder()
                .withMember("service", "com.example#MultiService")
                .withMember("package", "multi_mcp")
                .withMember("clientSdk", "smithy-rs")
                .withMember("clientCrate", "multi-client")
                .build();

        PluginContext context = createContext("integration-test.smithy", settings);
        new McpGeneratePlugin().execute(context);

        String tools = Files.readString(outputDir.resolve("src/tools.rs"));
        assertFalse(tools.contains("handle_internal_op"));
    }
}

package software.amazon.smithy.mcp.codegen;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import org.junit.jupiter.api.Test;
import software.amazon.smithy.build.FileManifest;
import software.amazon.smithy.build.PluginContext;
import software.amazon.smithy.model.Model;
import software.amazon.smithy.model.loader.ModelAssembler;
import software.amazon.smithy.model.node.Node;
import software.amazon.smithy.model.node.ObjectNode;

import static org.junit.jupiter.api.Assertions.*;

class SuperpositionEndToEndTest {

    @Test
    void generateSuperpositionMcpCrate() throws Exception {
        // Load all Superposition models
        ModelAssembler assembler = Model.assembler()
                .discoverModels(getClass().getClassLoader());

        // Add all model files from the example
        Path modelDir = Paths.get("../examples/superposition/model");
        Files.list(modelDir)
                .filter(p -> p.toString().endsWith(".smithy"))
                .forEach(assembler::addImport);

        Model model = assembler.assemble().unwrap();

        ObjectNode settings = Node.objectNodeBuilder()
                .withMember("service", "io.superposition#Superposition")
                .withMember("package", "superposition_mcp")
                .withMember("clientSdk", "smithy-rs")
                .withMember("clientCrate", "superposition-sdk")
                .withMember("runtimeVersion", "0.1.0")
                .build();

        Path outputDir = Paths.get("../examples/superposition/generated");
        FileManifest manifest = FileManifest.create(outputDir);
        PluginContext context = PluginContext.builder()
                .model(model)
                .fileManifest(manifest)
                .settings(settings)
                .build();

        new McpGeneratePlugin().execute(context);

        // Verify key files exist
        assertTrue(Files.exists(outputDir.resolve("Cargo.toml")));
        assertTrue(Files.exists(outputDir.resolve("src/lib.rs")));
        assertTrue(Files.exists(outputDir.resolve("src/types.rs")));
        assertTrue(Files.exists(outputDir.resolve("src/tools.rs")));
        assertTrue(Files.exists(outputDir.resolve("src/server.rs")));

        // Verify it generated tools for many operations
        String tools = Files.readString(outputDir.resolve("src/tools.rs"));
        assertTrue(tools.contains("handle_create_experiment"));
        assertTrue(tools.contains("handle_get_config"));
        assertTrue(tools.contains("handle_list_audit_logs"));
        assertTrue(tools.contains("handle_create_context"));
        assertTrue(tools.contains("handle_list_variables"));

        // Count the number of tool_info functions as a proxy for total operations
        long toolCount = tools.lines()
                .filter(l -> l.contains("pub fn tool_info_"))
                .count();

        // We expect all operations to be generated
        System.out.println("Generated " + toolCount + " MCP tools");
        assertTrue(toolCount >= 70, "Expected at least 70 tools, got " + toolCount);

        // Verify server has registrations
        String server = Files.readString(outputDir.resolve("src/server.rs"));
        assertTrue(server.contains("pub struct McpServer"));
        assertTrue(server.contains("register_tool"));
    }
}

package software.amazon.smithy.mcp.codegen;

import org.junit.jupiter.api.Test;
import software.amazon.smithy.model.node.Node;
import software.amazon.smithy.model.node.ObjectNode;

import static org.junit.jupiter.api.Assertions.*;

class McpPluginSettingsTest {

    @Test
    void parsesAllFields() {
        ObjectNode node = Node.objectNodeBuilder()
                .withMember("service", "com.example#MyService")
                .withMember("package", "my_mcp")
                .withMember("clientSdk", "smithy-rs")
                .withMember("clientCrate", "my-client")
                .withMember("runtimeVersion", "0.1.0")
                .build();

        McpPluginSettings settings = McpPluginSettings.fromNode(node);

        assertEquals("com.example#MyService", settings.getService());
        assertEquals("my_mcp", settings.getPackageName());
        assertEquals("smithy-rs", settings.getClientSdk());
        assertEquals("my-client", settings.getClientCrate());
        assertEquals("0.1.0", settings.getRuntimeVersion());
    }

    @Test
    void appliesDefaults() {
        ObjectNode node = Node.objectNodeBuilder()
                .withMember("service", "com.example#MyService")
                .withMember("package", "my_mcp")
                .withMember("clientCrate", "my-client")
                .build();

        McpPluginSettings settings = McpPluginSettings.fromNode(node);

        assertEquals("smithy-rs", settings.getClientSdk());
        assertEquals("0.1.0", settings.getRuntimeVersion());
    }

    @Test
    void failsWithoutRequiredFields() {
        ObjectNode node = Node.objectNodeBuilder().build();
        assertThrows(Exception.class, () -> McpPluginSettings.fromNode(node));
    }
}

