class McpGeneratePluginTest {

    @TempDir
    Path outputDir;

    @Test
    void pluginNameIsMcpRust() {
        McpGeneratePlugin plugin = new McpGeneratePlugin();
        assertEquals("mcp-rust", plugin.getName());
    }

    @Test
    void generatesRustCrate() throws Exception {
        Model model = Model.assembler()
                .discoverModels(getClass().getClassLoader())
                .addImport(getClass().getResource("plugin-test.smithy"))
                .assemble()
                .unwrap();

        ObjectNode settings = Node.objectNodeBuilder()
                .withMember("service", "com.example#WeatherService")
                .withMember("package", "weather_mcp")
                .withMember("clientSdk", "smithy-rs")
                .withMember("clientCrate", "weather-client")
                .build();

        FileManifest manifest = FileManifest.create(outputDir);
        PluginContext context = PluginContext.builder()
                .model(model)
                .fileManifest(manifest)
                .settings(settings)
                .build();

        McpGeneratePlugin plugin = new McpGeneratePlugin();
        plugin.execute(context);

        // Verify generated files exist
        assertTrue(Files.exists(outputDir.resolve("Cargo.toml")));
        assertTrue(Files.exists(outputDir.resolve("src/lib.rs")));
        assertTrue(Files.exists(outputDir.resolve("src/types.rs")));
        assertTrue(Files.exists(outputDir.resolve("src/tools.rs")));
        assertTrue(Files.exists(outputDir.resolve("src/server.rs")));

        // Verify Cargo.toml content
        String cargoToml = Files.readString(outputDir.resolve("Cargo.toml"));
        assertTrue(cargoToml.contains("name = \"weather_mcp\""));

        // Verify types.rs has the structs
        String types = Files.readString(outputDir.resolve("src/types.rs"));
        assertTrue(types.contains("pub struct GetWeatherInput"));
        assertTrue(types.contains("pub struct GetWeatherOutput"));

        // Verify types.rs has HashMap import
        assertTrue(types.contains("use std::collections::HashMap;"));

        // Verify tools.rs has bridge functions and correct imports
        String tools = Files.readString(outputDir.resolve("src/tools.rs"));
        assertTrue(tools.contains("handle_get_weather"));
        assertTrue(tools.contains("use smithy_mcp_runtime::{McpError, ToolInfo};"));
        assertTrue(tools.contains("use crate::types::*;"));
        assertFalse(tools.contains("use serde_json;"));

        // Verify server.rs has McpServer, router-based registration, and correct imports
        String server = Files.readString(outputDir.resolve("src/server.rs"));
        assertTrue(server.contains("pub struct McpServer"));
        assertTrue(server.contains("use std::sync::Arc;"));
        assertTrue(server.contains("use smithy_mcp_runtime::{McpError, Router};"));
        assertTrue(server.contains("use crate::types::*;"));
        assertTrue(server.contains("router.register_tool("));
        assertTrue(server.contains("pub async fn serve_stdio(self)"));
        assertTrue(server.contains("pub fn into_router(self) -> Router"));
        assertFalse(server.contains("call_tool"));
    }
}

