package software.amazon.smithy.mcp.codegen.generators;

import java.util.Arrays;
import java.util.List;
import org.junit.jupiter.api.Test;
import software.amazon.smithy.model.Model;
import software.amazon.smithy.model.shapes.OperationShape;
import software.amazon.smithy.model.shapes.ShapeId;

import static org.junit.jupiter.api.Assertions.*;

class ServerGeneratorTest {

    private Model loadModel() {
        return Model.assembler()
                .discoverModels(getClass().getClassLoader())
                .addImport(getClass().getResource("tool-test.smithy"))
                .assemble()
                .unwrap();
    }

    @Test
    void generatesSmithyRsServer() {
        Model model = loadModel();
        OperationShape op = model.expectShape(
                ShapeId.from("com.example#GetWeather"), OperationShape.class);
        List<OperationShape> ops = Arrays.asList(op);

        ServerGenerator gen = new ServerGenerator(model, "smithy-rs", "weather_client");
        String code = gen.generate(ops);

        assertTrue(code.contains("pub struct McpServer"));
        assertTrue(code.contains("router: Router,"));
        assertFalse(code.contains("client: weather_client::Client,"));
        assertTrue(code.contains("pub fn new(client: weather_client::Client)"));
        assertTrue(code.contains("let client = Arc::new(client);"));
        assertTrue(code.contains("let c = client.clone();"));
        assertTrue(code.contains("router.register_tool(tools::tool_info_get_weather(), move |params|"));
        assertTrue(code.contains("let client = c.clone();"));
        assertTrue(code.contains("async move { tools::handle_get_weather(&client, params).await }"));
        assertTrue(code.contains("pub async fn serve_stdio(self) -> Result<(), Box<dyn std::error::Error>>"));
        assertTrue(code.contains("smithy_mcp_runtime::serve_stdio(self.router).await"));
        assertTrue(code.contains("pub fn into_router(self) -> Router"));
        assertFalse(code.contains("call_tool"));
        assertFalse(code.contains("into_http_handler"));
    }

    @Test
    void generatesCustomServer() {
        Model model = loadModel();
        OperationShape op = model.expectShape(
                ShapeId.from("com.example#GetWeather"), OperationShape.class);
        List<OperationShape> ops = Arrays.asList(op);

        ServerGenerator gen = new ServerGenerator(model, "custom", "weather_client");
        String code = gen.generate(ops);

        assertTrue(code.contains("pub trait ToolHandler"));
        assertTrue(code.contains("async fn get_weather"));
        assertTrue(code.contains("pub fn new(handler: Arc<dyn ToolHandler>)"));
        assertTrue(code.contains("let h = handler.clone();"));
        assertTrue(code.contains("router.register_tool(tools::tool_info_get_weather(), move |params|"));
        assertTrue(code.contains("let handler = h.clone();"));
        assertTrue(code.contains("async move { tools::handle_get_weather(&*handler, params).await }"));
        assertTrue(code.contains("pub async fn serve_stdio(self) -> Result<(), Box<dyn std::error::Error>>"));
        assertTrue(code.contains("pub fn into_router(self) -> Router"));
        assertFalse(code.contains("call_tool"));
