package software.amazon.smithy.mcp.codegen.util;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class RustTypeMapperTest {

    @Test
    void mapsSimpleTypes() {
        assertEquals("String", RustTypeMapper.simpleShapeToRustType("String"));
        assertEquals("i32", RustTypeMapper.simpleShapeToRustType("Integer"));
        assertEquals("i64", RustTypeMapper.simpleShapeToRustType("Long"));
        assertEquals("f32", RustTypeMapper.simpleShapeToRustType("Float"));
        assertEquals("f64", RustTypeMapper.simpleShapeToRustType("Double"));
        assertEquals("bool", RustTypeMapper.simpleShapeToRustType("Boolean"));
        assertEquals("Vec<u8>", RustTypeMapper.simpleShapeToRustType("Blob"));
        assertEquals("String", RustTypeMapper.simpleShapeToRustType("Timestamp"));
    }

    @Test
    void mapsJsonSchemaTypes() {
        assertEquals("\"string\"", RustTypeMapper.simpleShapeToJsonSchemaType("String"));
        assertEquals("\"integer\"", RustTypeMapper.simpleShapeToJsonSchemaType("Integer"));
        assertEquals("\"integer\"", RustTypeMapper.simpleShapeToJsonSchemaType("Long"));
        assertEquals("\"number\"", RustTypeMapper.simpleShapeToJsonSchemaType("Float"));
        assertEquals("\"number\"", RustTypeMapper.simpleShapeToJsonSchemaType("Double"));
        assertEquals("\"boolean\"", RustTypeMapper.simpleShapeToJsonSchemaType("Boolean"));
    }

    @Test
    void convertsToSnakeCase() {
        assertEquals("get_weather", RustTypeMapper.toSnakeCase("GetWeather"));
        assertEquals("search_documents", RustTypeMapper.toSnakeCase("SearchDocuments"));
        assertEquals("my_op", RustTypeMapper.toSnakeCase("MyOp"));
    }

    @Test
    void convertsToPascalCase() {
        assertEquals("GetWeather", RustTypeMapper.toPascalCase("get_weather"));
        assertEquals("MyOp", RustTypeMapper.toPascalCase("my_op"));
    }

    @Test
    void detectsRustReservedKeywords() {
        assertTrue(RustTypeMapper.isRustReservedKeyword("type"));
        assertTrue(RustTypeMapper.isRustReservedKeyword("override"));
        assertTrue(RustTypeMapper.isRustReservedKeyword("match"));
        assertTrue(RustTypeMapper.isRustReservedKeyword("ref"));
        assertTrue(RustTypeMapper.isRustReservedKeyword("async"));
        assertFalse(RustTypeMapper.isRustReservedKeyword("city"));
        assertFalse(RustTypeMapper.isRustReservedKeyword("name"));
    }

    @Test
    void sanitizesEnumVariants() {
        // Backwards-compat single-arg form (no smithy `name` available) —
        // falls back to canonicalising the value.
        assertEquals("V1_0", RustTypeMapper.sanitizeEnumVariant("1.0"));
        assertEquals("V2_5", RustTypeMapper.sanitizeEnumVariant("2.5"));
        assertEquals("HighPriority", RustTypeMapper.sanitizeEnumVariant("high-priority"));
        assertEquals("Sunny", RustTypeMapper.sanitizeEnumVariant("SUNNY"));
    }

    @Test
    void sanitizesEnumVariantsUsingSmithyName() {
        // When the smithy enum exposes a `name`, prefer it — this matches
        // smithy-rs's variant-name canonicalisation. e.g. for
        // `enum OrgStatus { PENDING_KYB = "PendingKyb" }` smithy-rs emits
        // `OrgStatus::PendingKyb`, so the MCP side must too.
        assertEquals("PendingKyb", RustTypeMapper.sanitizeEnumVariant("PendingKyb", "PENDING_KYB"));
        assertEquals("Active", RustTypeMapper.sanitizeEnumVariant("Active", "ACTIVE"));
        assertEquals("Inactive", RustTypeMapper.sanitizeEnumVariant("Inactive", "INACTIVE"));
        // `enum FunctionRuntimeVersion { V1 = "1.0" }` — name `V1` is a
        // valid Rust ident, so we use it verbatim (after the PascalCase
        // pass it stays `V1`).
        assertEquals("V1", RustTypeMapper.sanitizeEnumVariant("1.0", "V1"));
    }

    @Test
    void toUpperCamelCaseHandlesAllCaps() {
        // ALL_CAPS_WITH_UNDERSCORES → AllCapsWithUnderscores
        assertEquals("PendingKyb", RustTypeMapper.toUpperCamelCase("PENDING_KYB"));
        assertEquals("Sunny", RustTypeMapper.toUpperCamelCase("SUNNY"));
        assertEquals("V1", RustTypeMapper.toUpperCamelCase("V1"));
        // PascalCase / camelCase should round-trip cleanly.
        assertEquals("PascalCase", RustTypeMapper.toUpperCamelCase("PascalCase"));
        assertEquals("CamelCase", RustTypeMapper.toUpperCamelCase("camelCase"));
        assertEquals("HighPriority", RustTypeMapper.toUpperCamelCase("high-priority"));
        // Dots, kebab, and spaces all act as word boundaries.
        assertEquals("OneTwoThree", RustTypeMapper.toUpperCamelCase("one.two-three"));
    }
}

