        // ThingResponse is reachable from GetThing as the top-level output (so it
        // gets a top-level impl tied to GetThingOutput). It should NOT also be
        // emitted as a nested-struct impl going to thing_sdk::types::ThingResponse,
        // because that would conflict with the operation-level impl.
        String code = generate();
        // Only one impl per direction; the top-level wins (it lives under
        // operation::get_thing, not types::).
        long countSdkTypesThing = code.lines()
                .filter(l -> l.contains("impl From<thing_sdk::types::ThingResponse>"))
                .count();
        assertEquals(0, countSdkTypesThing,
                "Top-level output shape must not also be emitted as nested:\n" + code);
    }
}

package software.amazon.smithy.mcp.codegen.generators;

import org.junit.jupiter.api.Test;
import software.amazon.smithy.model.Model;
import software.amazon.smithy.model.shapes.Shape;
import software.amazon.smithy.model.shapes.ShapeId;
import software.amazon.smithy.model.shapes.StructureShape;

import static org.junit.jupiter.api.Assertions.*;

class StructureGeneratorTest {

    private Model loadModel() {
        return Model.assembler()
                .addImport(getClass().getResource("struct-test.smithy"))
                .assemble()
                .unwrap();
    }

    @Test
    void generatesSimpleStruct() {
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#GetWeatherInput"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("#[derive(Debug, Clone, Serialize, Deserialize)]"));
        assertTrue(code.contains("pub struct GetWeatherInput {"));
        assertTrue(code.contains("pub city: String,"));
    }

    @Test
    void generatesOptionalFields() {
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#GetWeatherOutput"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("pub temperature: f32,"));
        assertTrue(code.contains("pub humidity: Option<f32>,"));
    }

    @Test
    void generatesEnumType() {
        Model model = loadModel();
        Shape shape = model.expectShape(ShapeId.from("com.example#WeatherCondition"));

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generateEnum(shape);

        assertTrue(code.contains("#[derive(Debug, Clone, Serialize, Deserialize)]"));
        assertTrue(code.contains("pub enum WeatherCondition {"));
        assertTrue(code.contains("#[serde(rename = \"SUNNY\")]"));
        assertTrue(code.contains("Sunny,"));
        assertTrue(code.contains("#[serde(rename = \"CLOUDY\")]"));
        assertTrue(code.contains("Cloudy,"));
        assertTrue(code.contains("#[serde(rename = \"RAINY\")]"));
        assertTrue(code.contains("Rainy,"));
    }

    @Test
    void structReferencesEnumType() {
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#ForecastInput"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("pub condition: WeatherCondition,"),
                "Expected enum type reference, got:\n" + code);
    }

    @Test
    void structWithTimestampField() {
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#ForecastInput"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("pub timestamp: String,"),
                "Expected String type for timestamp, got:\n" + code);
    }

    @Test
    void generatesEnumWithNumericValues() {
        Model model = loadModel();
        Shape shape = model.expectShape(ShapeId.from("com.example#VersionEnum"));

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generateEnum(shape);

        // Variant names follow the smithy enum `name` (matches smithy-rs).
        // Numeric serde values come from the enum value.
        assertTrue(code.contains("#[serde(rename = \"1.0\")]"), "Expected serde rename for 1.0, got:\n" + code);
        assertTrue(code.contains("OnePointZero,"), "Expected OnePointZero variant, got:\n" + code);
        assertTrue(code.contains("#[serde(rename = \"2.5\")]"), "Expected serde rename for 2.5, got:\n" + code);
        assertTrue(code.contains("TwoPointFive,"), "Expected TwoPointFive variant, got:\n" + code);
        assertTrue(code.contains("#[serde(rename = \"high-priority\")]"), "Expected serde rename for high-priority, got:\n" + code);
        assertTrue(code.contains("HighPriority,"), "Expected HighPriority variant, got:\n" + code);
    }

    @Test
    void generatesEnumPicksSmithyNameOverValue() {
        // Mirrors the superposition `OrgStatus` case where the smithy
        // model uses UPPER_SNAKE_CASE `name`s with the human-friendly
        // string value (e.g. `PENDING_KYB = "PendingKyb"`). The Rust
        // variant identifier must match smithy-rs's output (`PendingKyb`)
        // so `From`/`Into` impls line up at compile time.
        Model model = loadModel();
        Shape shape = model.expectShape(ShapeId.from("com.example#OrgStatus"));

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generateEnum(shape);

        assertTrue(code.contains("#[serde(rename = \"Active\")]"), "Expected serde rename for Active, got:\n" + code);
        assertTrue(code.contains("Active,"), "Expected Active variant, got:\n" + code);
        assertTrue(code.contains("#[serde(rename = \"PendingKyb\")]"), "Expected serde rename for PendingKyb, got:\n" + code);
        assertTrue(code.contains("PendingKyb,"), "Expected PendingKyb variant, got:\n" + code);
    }

    @Test
    void generatesStructWithReservedKeywords() {
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#ReservedKeywordStruct"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("#[serde(rename = \"type\")]"), "Expected serde rename for type, got:\n" + code);
        assertTrue(code.contains("pub r#type: String,"), "Expected r#type field, got:\n" + code);
        assertTrue(code.contains("#[serde(rename = \"override\")]"), "Expected serde rename for override, got:\n" + code);
        assertTrue(code.contains("pub r#override: Option<String>,"), "Expected r#override field, got:\n" + code);
        assertTrue(code.contains("#[serde(rename = \"match\")]"), "Expected serde rename for match, got:\n" + code);
        assertTrue(code.contains("pub r#match: Option<i32>,"), "Expected r#match field, got:\n" + code);
    }

    @Test
    void structReferencesUnionByTypedName() {
        // Smithy unions are now first-class — a struct member that points at
        // a union gets the union's bare name in MCP-side Rust, matching the
        // smithy-rs SDK (so `From`/`Into` impls compose).
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#UnionRefStruct"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("pub data: ExampleUnion,"),
                "Expected typed union reference, got:\n" + code);
    }

    @Test
    void generatesUnionType() {
        Model model = loadModel();
        software.amazon.smithy.model.shapes.UnionShape shape = model.expectShape(
                ShapeId.from("com.example#ExampleUnion"),
                software.amazon.smithy.model.shapes.UnionShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generateUnion(shape);

        assertTrue(code.contains("pub enum ExampleUnion {"), "Expected union as Rust enum, got:\n" + code);
        // Member names are PascalCased to match smithy-rs; the serde rename
        // preserves the wire-form member name.
        assertTrue(code.contains("#[serde(rename = \"stringValue\")]"), "Expected serde rename for stringValue, got:\n" + code);
        assertTrue(code.contains("StringValue(String),"), "Expected StringValue payload variant, got:\n" + code);
        assertTrue(code.contains("#[serde(rename = \"intValue\")]"), "Expected serde rename for intValue, got:\n" + code);
        assertTrue(code.contains("IntValue(i32),"), "Expected IntValue payload variant, got:\n" + code);
    }

    @Test
    void generatesUnionWithUnitMember() {
        // Unions with a `Unit`-typed member become unit variants (no
        // payload) — matches smithy-rs, e.g. `DimensionType::Regular`
        // for `REGULAR: Unit`.
        Model model = loadModel();
        software.amazon.smithy.model.shapes.UnionShape shape = model.expectShape(
                ShapeId.from("com.example#UnitUnion"),
                software.amazon.smithy.model.shapes.UnionShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generateUnion(shape);

        assertTrue(code.contains("#[serde(rename = \"REGULAR\")]"), "Expected serde rename, got:\n" + code);
        assertTrue(code.contains("Regular,") && !code.contains("Regular("),
                "Expected unit variant for Unit-typed member, got:\n" + code);
        assertTrue(code.contains("Cohort(String),"), "Expected payloaded variant, got:\n" + code);
    }

    @Test
    void structReferencesBareStringAsString() {
        // A custom-named string with no @enum trait should map to Rust
        // `String`, not `serde_json::Value` — matches smithy-rs.
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#BareStringStruct"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("pub label: String,"),
                "Expected bare-string member to map to Rust String, got:\n" + code);
    }

    @Test
    void structReferencesCustomTimestampAsString() {
        // A custom-named timestamp (e.g. `@timestampFormat("date-time")
        // timestamp DateTime`) must map to `String` on the MCP side,
        // matching smithy.api#Timestamp.
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#CustomTimestampStruct"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("pub created_at: String,"),
                "Expected custom-timestamp member to map to String, got:\n" + code);
    }

    @Test
    void structReferencesNestedStructure() {
        // Verifies the typed-struct path through resolveShapeType: a
        // member referencing another smithy structure must emit that
        // structure's bare name, not `serde_json::Value`.
        Model model = loadModel();
        StructureShape shape = model.expectShape(
                ShapeId.from("com.example#StructRefStruct"), StructureShape.class);

        StructureGenerator gen = new StructureGenerator(model);
        String code = gen.generate(shape);

        assertTrue(code.contains("pub inner: ForecastDetail,"),
                "Expected typed nested-struct reference, got:\n" + code);
    }
}

$version: "2.0"

namespace io.superposition

use software.amazon.smithy.mcp#mcpTool

@documentation("Secrets are encrypted key-value pairs stored at the workspace level. Secret values are encrypted with workspace-specific encryption keys and support key rotation.")
resource Secret {
    identifiers: {
        workspace_id: String
        org_id: String
        name: String
    }
    properties: {
        value: String
        description: String
        change_reason: String
        created_by: String
        created_at: DateTime
        last_modified_by: String
        last_modified_at: DateTime
    }
    list: ListSecrets
    update: UpdateSecret
    read: GetSecret
    delete: DeleteSecret
    operations: [
        CreateSecret
    ]
}

@documentation("Response structure for secret operations. Secret values are never returned for security.")
structure SecretResponse {
    @required
    name: String

    @required
    description: String

    @required
    change_reason: String

    @required
    created_by: String

    @required
    created_at: DateTime

    @required
    last_modified_by: String

    @required
    last_modified_at: DateTime
}

list SecretList {
    member: SecretResponse
}

enum SecretSortOn {
    NAME = "name"
    CREATED_AT = "created_at"
    LAST_MODIFIED_AT = "last_modified_at"
}

@documentation("Creates a new encrypted secret with the specified name and value. The secret is encrypted with the workspace's current encryption key. Secret values are never returned in responses for security.")
@http(method: "POST", uri: "/secrets")
@tags(["Secrets"])
@mcpTool(description: "Creates a new encrypted secret with the specified name and value. The secret is encrypted with the workspace's current encryption key. Secret values are never returned in responses for security.")
operation CreateSecret {
    input := for Secret with [WorkspaceMixin] {
        @required
        name: String

        @required
        @documentation("Plaintext value to be encrypted and stored.")
        value: String

        @required
        description: String

        @required
        change_reason: String
    }

    output: SecretResponse
}

@documentation("Updates an existing secret's value or description. The value is re-encrypted with the current workspace encryption key. Returns masked value.")
@idempotent
@http(method: "PATCH", uri: "/secrets/{name}")
@tags(["Secrets"])
@mcpTool(description: "Updates an existing secret's value or description. The value is re-encrypted with the current workspace encryption key. Returns masked value.")
operation UpdateSecret with [GetOperation] {
    input := for Secret with [WorkspaceMixin] {
        @httpLabel
        @required
        $name

        @documentation("New plaintext value to encrypt and store. If provided, will be encrypted with current key.")
        value: String

        description: String

        @required
        change_reason: String
    }

    output: SecretResponse
}

@documentation("Retrieves a paginated list of all secrets in the workspace with optional filtering and sorting. All secret values are masked.")
@readonly
@http(method: "GET", uri: "/secrets")
@tags(["Secrets"])
@mcpTool(description: "Retrieves a paginated list of all secrets in the workspace with optional filtering and sorting. All secret values are masked.")
operation ListSecrets {
    input := with [PaginationParams, WorkspaceMixin] {
        @httpQuery("name")
        @documentation("Filter by secret name.")
        @notProperty
        name: StringList

        @httpQuery("created_by")
        @documentation("Filter by the user who created the secret.")
        created_by: StringList

        @httpQuery("last_modified_by")
        @documentation("Filter by the user who last modified the secret.")
        last_modified_by: StringList

        @httpQuery("sort_on")
        @documentation("Field to sort the results by.")
        @notProperty
        sort_on: SecretSortOn

        @httpQuery("sort_by")
        @documentation("Sort order (ascending or descending).")
        @notProperty
        sort_by: SortBy
    }

    output := with [PaginatedResponse] {
        @required
        data: SecretList
    }
}

@documentation("Retrieves detailed information about a specific secret by its name. The value is masked for security.")
@readonly
@http(method: "GET", uri: "/secrets/{name}")
@tags(["Secrets"])
@mcpTool(description: "Retrieves detailed information about a specific secret by its name. The value is masked for security.")
operation GetSecret with [GetOperation] {
    input := for Secret with [WorkspaceMixin] {
        @httpLabel
        @required
        $name
    }

    output: SecretResponse
}

@documentation("Permanently deletes a secret from the workspace. The encrypted value is removed and cannot be recovered.")
@idempotent
@http(method: "DELETE", uri: "/secrets/{name}")
@tags(["Secrets"])
@mcpTool(description: "Permanently deletes a secret from the workspace. The encrypted value is removed and cannot be recovered.")
operation DeleteSecret with [GetOperation] {
    input := for Secret with [WorkspaceMixin] {
        @httpLabel
        @required
        $name
    }

    output: SecretResponse
}

@documentation("Secrets are encrypted key-value pairs stored at the workspace level. Secret values are encrypted with workspace-specific encryption keys and support key rotation.")
resource MasterKey {
    identifiers: {}
    properties: {}
    operations: [
        RotateMasterEncryptionKey
    ]
}

@documentation("Rotates the master encryption key across all workspaces")
@idempotent
@http(method: "POST", uri: "/master-encryption-key/rotate")
@tags(["Admin", "Encryption"])
@mcpTool(description: "Rotates the master encryption key across all workspaces")
operation RotateMasterEncryptionKey {
    output := {
        @required
        workspaces_rotated: Long

        @required
        total_secrets_re_encrypted: Long
    }
}
